package com.shego.dao;
import com.shego.model.Product; import com.shego.util.DBUtil; import java.sql.*; import java.util.*;
public class ProductDao { public List<Product> find(String keyword) throws SQLException { List<Product> list=new ArrayList<>(); String sql="SELECT id,name,description,price,stock,image_url FROM products WHERE name LIKE ? ORDER BY id DESC"; try(Connection c=DBUtil.getConnection(); PreparedStatement s=c.prepareStatement(sql)){s.setString(1,"%"+(keyword==null?"":keyword)+"%"); try(ResultSet r=s.executeQuery()){while(r.next()){Product p=new Product();p.setId(r.getInt("id"));p.setName(r.getString("name"));p.setDescription(r.getString("description"));p.setPrice(r.getDouble("price"));p.setStock(r.getInt("stock"));p.setImageUrl(r.getString("image_url"));list.add(p);}}} return list; } }
